import{z as o,x as i,o as E,c as d,q as l,j as s,D as e,d as r,s as B,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"Saltzer 端到端","description":"","frontmatter":{"title":"Saltzer 端到端","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/saltzer-e2e-paper.md","filePath":"cs/saltzer-e2e-paper.md","lastUpdated":1791063341000}'),p={name:"cs/saltzer-e2e-paper.md"};function C(D,a,h,c,m,f){const t=i("Mermaid");return E(),d("div",null,[a[2]||(a[2]=l('<h1 id="saltzer-端到端" tabindex="-1">Saltzer 端到端 <a class="header-anchor" href="#saltzer-端到端" aria-label="Permalink to &quot;Saltzer 端到端&quot;">​</a></h1><div class="epigraph"><p>功能只应放在端系统能完成且正确的那一层；下层的「几乎正确」不能代替两端的检查。</p><footer>—— Saltzer, Reed and Clark, End-to-End Arguments in System Design, ACM TOCS 1984</footer></div><p><a href="/cs/cerf-kahn-tcp">上一课</a>附录对照了 1974 年互联与可靠流设想。附录对照，不插入主干。主干已在<a href="/cs/layering-e2e">分层与端到端</a>用文件传送例子钉死论证，并在 CRC、TCP 校验、TLS 入口反复引用；这里对照 <strong>1984 原文的问题</strong>：在已有互联的世界上，可靠性、加密、去重该放哪一层。不重画五层图，也不把本篇插回 DMA 之后当第一课网络。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Cerf–Kahn 给出网关与主机协议。Saltzer 等的缺口是设计原则：链路重传挡不住中间内存出错，文件正确性只能在真正读写文件的两端用校验与重试保证。下层努力是性能。原文还谈加密与交付保证的同类结构。主干分层课已经取走这一句；附录对照原文如何用反例把原则写硬。</p><p><span class="marginnote">论证不是「不要 CRC」。主干<a href="/cs/frame-crc">CRC 在帧上</a> 明确：一跳检错降端到端重传频率。反对的是声称下层已经够了。</span></p><p><span class="marginnote">「端系统」就是通信真正发生在其上的那两台机器——存文件的服务器和读文件的工作站，而不是路径上的交换机、路由器。原则说的「两端」，指的就是这两台：只有它们既写又读那份文件，也只有它们的检查才覆盖全程。</span></p><p><span class="marginnote">常见误区：初学者容易以为「每跳 CRC 都过了，文件就一定没坏」。实际上包可能在路由器内存里待过——比特翻转发生在两次 CRC 之间的存储环节，链路检错全然看不见，只有两端对全文件再算一次校验和才能发现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>举文件传送、加密只在链路时换跳即明文、重复报文在中间去重仍可能在端点重复。结论：端到端能做对的功能，规格必须在端。主干<a href="/cs/tls-handshake">TLS</a> 把机密性放到会话两端，正是这条原则在安全课的实例。</p>',10)),(E(),s(n,null,{default:e(()=>[B(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20LINK%5B%22%E9%93%BE%E8%B7%AF%E5%B0%BD%E5%8A%9B%22%5D%20--%3E%20PERF%5B%22%E9%99%8D%E4%BD%8E%E9%87%8D%E4%BC%A0%E9%A2%91%E7%8E%87%22%5D%0A%20%20ENDS%5B%22%E7%9C%9F%E6%AD%A3%E4%B8%A4%E7%AB%AF%22%5D%20--%3E%20CORR%5B%22%E6%AD%A3%E7%A1%AE%E6%80%A7%E8%A7%84%E6%A0%BC%22%5D%0A%20%20CORR%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E5%88%86%E5%B1%82%E8%AF%BE%E5%B7%B2%E5%8F%96%E7%94%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[r("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"原则约束层间合同，使后课不会把 FCS 当成文件完整性，也不会把防火墙当成 TLS。它与 Lampson 矩阵正交：一个谈放哪一层，一个谈谁有权。Codd 下一篇把数据从指针网里抽出来，对象又换。",-1)),(E(),s(n,null,{default:e(()=>[B(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%90%8C%E4%B8%80%E5%8A%9F%E8%83%BD%3A%20%E5%8A%A0%E5%AF%86%2F%E6%A0%A1%E9%AA%8C%2F%E5%8E%BB%E9%87%8D%22%5D%20--%3E%20Q%7B%22%E6%94%BE%E5%9C%A8%E5%93%AA%E4%B8%80%E5%B1%82%3F%22%7D%0A%20%20Q%20--%20%22%E5%8F%AA%E6%94%BE%E9%93%BE%E8%B7%AF%2F%E4%B8%8B%E5%B1%82%22%20--%3E%20L1%5B%22%E6%AF%8F%E8%B7%B3%E5%90%84%E8%87%AA%E4%BF%9D%E8%AF%81%22%5D%0A%20%20L1%20--%3E%20MISS%5B%22%E4%B8%AD%E9%97%B4%E5%AD%98%E5%82%A8%E4%B8%8E%E4%B8%8A%E5%B1%82%E8%AF%AD%E4%B9%89%E4%B8%8D%E5%9C%A8%E4%BF%9D%E6%8A%A4%E8%8C%83%E5%9B%B4%22%5D%0A%20%20MISS%20--%3E%20GAP%5B%22%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%AD%A3%E7%A1%AE%E6%80%A7%E7%95%99%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20Q%20--%20%22%E8%A7%84%E6%A0%BC%E6%94%BE%E5%9C%A8%E4%B8%A4%E7%AB%AF%22%20--%3E%20E1%5B%22%E8%A6%86%E7%9B%96%E5%85%A8%E7%A8%8B%E8%B7%AF%E5%BE%84%22%5D%0A%20%20E1%20--%3E%20LOWER%5B%22%E4%B8%8B%E5%B1%82%E4%BB%8D%E5%8F%AF%E5%8A%A0%E5%81%9A%2C%20%E6%8D%A2%E6%88%90%E6%80%A7%E8%83%BD%22%5D%0A%20%20LOWER%20--%3E%20OK%5B%22%E6%AD%A3%E7%A1%AE%E6%80%A7%E8%A7%84%E6%A0%BC%E9%97%AD%E5%90%88%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>这张图回答的问题是：把一个功能放下层与放两端，各自买到了什么、漏掉了什么——下层做是性能优化、规格必须在端做是正确性来源，两条分支的终点不同。</p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>主干网络第一课必须接 OS 的 DMA 缺口，用教学五层往下走进帧。把 1984 插在 Cerf–Kahn 之后当课序，读者会以为先读论文再碰 MAC。本栏已在分层课取用原则；附录只对照原文论证，不改变「帧在 IP 前」的课序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把端到端与网络中立政策混成一篇。也不要在附录里开主动网络。下一篇对照 Codd 1970 关系模型。</p><p>对照结束应回到主干<a href="/cs/layering-e2e">分层与端到端</a>。1984 文不插入 virtio 与帧之间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Saltzer, Reed and Clark 1984：正确性在真正两端。</li><li>主干分层课已取用；本篇不插入网络课序。</li><li>出处：Saltzer, Reed and Clark, <em>ACM TOCS</em> 1984。</li></ul>',8))])}const u=o(p,[["render",C]]);export{F as __pageData,u as default};
